	["{npc:12944} to Exalted"] = "{npc:12944} jusqu'à Exalté",
	-- {item:17012} Core Leather · {item:11370} Dark Iron Ore · {area:2717} Molten Core · {item:19165} Flarecore Leggings · {item:19157} Chromatic Gauntlets · {item:19162} Corehound Belt · {item:19163} Molten Belt · {item:17013} Dark Iron Leggings · {item:19164} Dark Iron Gauntlets · {item:16988} Fiery Chain Shoulders · {item:19166} Black Amnesty · {item:273577} Enchant Weapon - Mighty Intellect · {item:19170} Ebon Hand · {item:20039} Dark Iron Boots
	["Revered to Exalted is 21,000 more: 105 cores or Bloods, 280 {item:17012} or 4,200 {item:11370}. The {area:2717} materials come from the raid, so a guild or the auction house does most of the work. Revered opens {item:19165} 9g, {item:19157} 9g, {item:19162} 9g, {item:19163} 9g, {item:17013} 18g, {item:19164} 8g, {item:16988} 20g, {item:19166} 7g, Blackfury 7g and {item:273577} 10g. Exalted opens the epic weapon plans {item:19170}, Blackguard and Nightfall (12g each) and {item:20039} 8g."] = "De Révéré à Exalté, il faut 21 000 de plus : 105 noyaux ou sangs, 280 {item:17012} ou 4 200 {item:11370}. Les matériaux du {area:2717} viennent du raid : une guilde ou l'hôtel des ventes fait l'essentiel du travail. Révéré débloque {item:19165} 9 po, {item:19157} 9 po, {item:19162} 9 po, {item:19163} 9 po, {item:17013} 18 po, {item:19164} 8 po, {item:16988} 20 po, {item:19166} 7 po, Fureur noire 7 po et {item:273577} 10 po. Exalté débloque les plans d'armes épiques {item:19170}, Garde noire et Crépuscule (12 po chacun) et {item:20039} 8 po.",

	-- No longer in the guide (its English changed or it went away): reuse or delete.
	-- ["Back to Burninate"] = "Retour auprès de Burninate",
	-- ["Keep turning in {area:2717} materials and {item:11099} at Lokhtos until Exalted."] = "Continuez à rendre des matériaux de {area:2717} et du {item:11099} auprès de Lokhtos jusqu'à Exalté.",
	-- ["Restoring Fiery Flux Supplies repeats in three versions: {item:3356}, Iron Bars or {item:4234}, each with Coal and an {item:18944}. Incendosaurs (level 47-49) in the north of {zone:1427} drop a scale every time; Burninate himself sells Coal."] = "Réapprovisionnement en flux embrasé se répète en trois versions : {item:3356}, Barres de fer ({item:3575}) ou {item:4234}, chacune avec du Charbon et une {item:18944}. Les Incendosaures (niveau 47-49) du nord de la {zone:1427} lâchent une écaille à chaque fois ; Burninate lui-même vend le Charbon.",
	-- ["The plans lie in the {area:1443} of the Cauldron, guarded by {object:147516} dwarves. {object:147516} dwarves also drop {item:18945}, which Burninate takes for Gaining Acceptance."] = "Les plans se trouvent dans {area:1443} du Chaudron, gardés par des nains {object:147516}. Les nains {object:147516} lâchent aussi {item:18945}, que Burninate prend pour Se faire accepter.",
	-- ["The {area:2717} materials carry the rest: Fiery Cores drop from Firewalkers, Flameguards and Firelords, and Lava Cores from Lava Elementals, Lava Reavers and Molten Destroyers there. {item:11382} comes from Molten Destroyers and rarely elsewhere."] = "Les matériaux de {area:2717} font le reste : les Noyaux de feu tombent sur les Marchefeux, Gardes des flammes et Seigneurs du feu, et les Noyaux de lave sur les Élémentaires de lave, Ravageurs de lave et Destructeurs de lave sur place. {item:11382} vient des Destructeurs de lave et rarement d'ailleurs.",
	-- ["{area:1446} is the scaffolded camp on the north-west rim of the Cauldron, with a flight point. Everyone starts Neutral with the Brotherhood. These seven quests (level 48 to 50) pay 100 reputation each: 700 in all, 800 with the pillow below. In Classic a quest pays less once it is 6 or more levels below you, only 20 each at 60, so do them while you level through {zone:1427} if you can; your first turn-in shows which. {npc:14624}'s {quest:7722} also opens his {item:18942} turn-ins, so it is needed at any level. The numbers in this guide leave out the Legacy perk Diplomat, which adds up to 10%."] = "Le {area:1446} est le camp échafaudé sur le rebord nord-ouest du Chaudron, avec un maître de vol. Tout le monde commence Neutre avec la Confrérie. Ces sept quêtes (niveau 48 à 50) rapportent 100 de réputation chacune : 700 en tout, 800 avec l'oreiller ci-dessous. Dans Classic, une quête rapporte moins dès qu'elle est 6 niveaux ou plus sous le vôtre, seulement 20 chacune au niveau 60 : faites-les si possible en traversant la {zone:1427} ; votre première remise vous le dira. La quête {quest:7722} de {npc:14624} débloque aussi ses remises de {item:18942} : elle est donc nécessaire à tout niveau. Les chiffres de ce guide ne comptent pas l'atout d'Héritage Diplomate, qui ajoute jusqu'à 10 %.",
	-- ["{area:1446}, on the scaffolds in the north-west of {zone:1427}, is the Brotherhood's outpost. The {faction:59} starts out Neutral. Forever's Legacy Diplomat perk increases reputation gains."] = "{area:1446}, sur les échafaudages au nord-ouest de {zone:1427}, est l'avant-poste de la Confrérie. Votre réputation auprès de {faction:59} commence à Neutre. L'atout Diplomate de l'Héritage de Forever augmente les gains de réputation.",
	-- ["{area:2717} materials: Favor Amongst the Brotherhood, {item:17010}, {item:17011}, {item:17012} and {item:11382}, all repeatable at Lokhtos."] = "Matériaux de {area:2717} : Faveur auprès de la Confrérie, {item:17010}, {item:17011}, {item:17012} et {item:11382}, toutes répétables auprès de Lokhtos.",
	-- ["{faction:59} to Exalted"] = "{faction:59} jusqu'à Exalté",
	-- ["{faction:59} to Revered"] = "{faction:59} jusqu'à Révéré",
	-- ["{item:11099}: Favor Amongst the Brotherhood, {item:11099} at Lokhtos, repeatable."] = "{item:11099} : Faveur auprès de la Confrérie, {item:11099}, auprès de Lokhtos, répétable.",
	-- ["{item:18942} supplies to Friendly"] = "Réserves de {item:18942} jusqu'à Amical",
	-- ["{npc:12944} to Honored"] = "{npc:12944} jusqu'à Honoré",
	-- ["{npc:12944} trades in the Grim Guzzler inside {area:1584}. His Favor Amongst the Brotherhood turn-ins take {item:11099} (mined from Dark Iron Deposits with {skill:186}), {item:11382}, {item:17010}, {item:17011} and {item:17012}. {npc:14387} at the {area:1445} entrance offers attunement to the {area:2717}."] = "{npc:12944} commerce au Sinistre dévoreur, dans les {area:1584}. Ses remises Faveur auprès de la Confrérie prennent du {item:11099} (extrait des Gisements de sombrefer ({object:165658}) avec {skill:186}), du {item:11382}, des {item:17010}, des {item:17011} et du {item:17012}. {npc:14387}, à l'entrée du {area:1445}, propose l'harmonisation au {area:2717}.",
	-- ["{npc:14624}: Restoring Fiery Flux Supplies"] = "{npc:14624} : Réapprovisionnement en flux embrasé",
}
